def run_min_stack_ops(ops):
    stack = []
    min_stack = []
    output = []

    for op, arg in ops:
        if op == 'push':
            stack.append(arg)
            if min_stack:
                min_stack.append(min(arg, min_stack[-1]))
            else:
                min_stack.append(arg)
        elif op == 'pop':
            stack.pop()
            min_stack.pop()
        elif op == 'top':
            output.append(stack[-1])
        elif op == 'getMin':
            output.append(min_stack[-1])

    return output

